int of_flash_probe_bt1_rom ( struct platform_device * pdev , struct device_node * np , struct map_info * map ) { struct device * dev = & pdev -> dev ; if ( ! of_device_is_compatible ( np , "mtd-rom" ) ) { dev_info ( dev , "No mtd-rom compatible string\n" ) ; return 0 ; } if ( ! of_device_is_compatible ( np , "baikal,bt1-int-rom" ) ) { return 0 ; } map -> read = bt1_rom_map_read ; map -> copy_from = bt1_rom_map_copy_from ; return 0 ; } 